/*
 * Bluetooth Serial Bridge — Board A
 * Sends any Serial Monitor input via Bluetooth.
 * Received Bluetooth data is printed to Serial Monitor.
 *
 * Open the Serial Monitor for both boards to chat.
 */

#include <BluetoothSerial.h>

BluetoothSerial SerialBT;

void setup() {
  Serial.begin(115200);
  SerialBT.begin("ESP32_BT_A");
  Serial.println("Board A: Bluetooth started as ESP32_BT_A");
  Serial.println("Type in Serial Monitor to send via Bluetooth");
}

void loop() {
  // Read from computer Serial Monitor and send to Bluetooth
  if (Serial.available()) {
    SerialBT.write(Serial.read());
  }

  // Read from Bluetooth and send to computer Serial Monitor
  if (SerialBT.available()) {
    Serial.write(SerialBT.read());
  }

  delay(20);
}

